    "son ejércitos en campaña (cada figurita, unos # hombres; el pendón dorado, su general). Clic en uno tuyo: se ilumina hasta dónde llega esta estación; clic en una casilla para marchar, en una ciudad enemiga (roja) para asediarla.": "são exércitos em campanha (cada figura, cerca de # homens; o pendão dourado, seu general). Clique em um dos seus: acende-se até onde ele chega nesta estação; clique em uma casa para marchar, ou em uma cidade inimiga (vermelha) para sitiá-la.",
    "Rueda o pellizco para acercar; arrastra para moverte. El minimapa lleva la vista a otro lugar.": "Roda ou pinça para aproximar; arraste para se mover. O minimapa leva a vista a outro lugar.",
