    "Recluta": "Recrute",
    "En la pestaña Provincia, sección «Reclutar», compra levas con oro en una de tus ciudades. Pasa el ratón sobre cada clase para ver sus fuerzas y debilidades.": "Na aba Província, seção «Recrutar», compre levas com ouro em uma de suas cidades. Passe o mouse sobre cada classe para ver suas forças e fraquezas.",
    "Sal a campaña": "Vá à campanha",
    "En la sección «Ejército» forma un ejército: aparecerá un estandarte en el mapa. Tócalo y luego una casilla iluminada para marchar.": "Na seção «Exército», forme um exército: um estandarte aparecerá no mapa. Toque nele e depois em uma casa iluminada para marchar.",
    "Gobierna": "Governe",
    "Las pestañas de arriba llevan a la Corte, la Diplomacia, el Tesoro y el Progreso. No hace falta tocarlo todo: empieza por lo que te llame.": "As abas de cima levam à Corte, à Diplomacia, ao Tesouro e ao Progresso. Não é preciso mexer em tudo: comece pelo que lhe chamar a atenção.",
    "Pasa la estación": "Passe a estação",
