    "Defiendes la plaza: coloca tus unidades dentro de la muralla (la zona clara). Arqueros junto al lienzo, la línea detrás y la caballería al fondo, lista para salir por una puerta.": "Você defende a praça: posicione suas unidades dentro da muralha (a zona clara). Arqueiros junto ao lanço, a linha atrás e a cavalaria ao fundo, pronta para sair por um portão.",
    "Asedio: despliega en cualquier punto alrededor de la plaza (la zona clara). Arietes a las puertas, torres y escalas contra los lienzos, catapultas a tiro de la muralla; rodearla reparte a la guarnición.": "Cerco: posicione-se em qualquer ponto ao redor da praça (a zona clara). Aríetes nos portões, torres e escadas contra os lanços, catapultas ao alcance da muralha; cercá-la divide a guarnição.",
    "Arrastra tus unidades dentro de la franja clara. Lanceros al frente frenan la caballería; arqueros detrás; caballería en las alas. Bosque: cubre y frena jinetes. Colina: mejor tiro y defensa. Río: frena y debilita; usa los vados.": "Arraste suas unidades dentro da faixa clara. Lanceiros à frente detêm a cavalaria; arqueiros atrás; cavalaria nas alas. Floresta: dá cobertura e freia cavaleiros. Colina: melhor tiro e defesa. Rio: freia e enfraquece; use os vaus.",
