    "Toca una unidad para elegirla; mantén pulsada otra para sumarla, o mantén pulsado el terreno y arrastra para rodear varias. Luego toca el destino (o arrastra) y ⚔︎ + enemigo para atacar.{}{}": "Toque em uma unidade para escolhê-la; mantenha outra pressionada para somá-la, ou mantenha o terreno pressionado e arraste para cercar várias. Depois toque no destino (ou arraste) e em ⚔︎ + inimigo para atacar.{}{}",
