    "Dicen que {} fue mozo de mulas antes de mandar una línea de escudos.": "Dizem que {} foi moço de mulas antes de comandar uma linha de escudos.",
    "Los berserkers mordieron sus escudos y cayeron sobre el enemigo como lobos.": "Os berserkers morderam seus escudos e caíram sobre o inimigo como lobos.",
    "La furia de los berserkers no bastó: cuando se apagó, quedaron indefensos.": "A fúria dos berserkers não bastou: quando se apagou, ficaram indefesos.",
    "Los elefantes rompieron la línea enemiga y aplastaron cuanto hallaron.": "Os elefantes romperam a linha inimiga e esmagaram tudo o que encontraram.",
    "Los elefantes se desbocaron y pisotearon a los suyos.": "Os elefantes dispararam e pisotearam os seus.",
    "Los caballos enemigos huyeron espantados por el olor de las bestias.": "Os cavalos inimigos fugiram, espantados pelo cheiro das feras.",
    "Ni el espanto de las bestias salvó la jornada.": "Nem o pavor das feras salvou a jornada.",
    "El fuego que no se apaga con agua devoró las filas contrarias.": "O fogo que a água não apaga devorou as fileiras inimigas.",
    "El fuego líquido ardió en vano.": "O fogo líquido ardeu em vão.",
    "El muro de escudos no cedió un palmo en toda la jornada.": "A parede de escudos não cedeu um palmo em toda a jornada.",
    "El muro de escudos aguantó hasta que ya no hubo hombres que lo sostuvieran.": "A parede de escudos aguentou até que não houve mais homens para sustentá-la.",
    "La tortuga avanzó bajo la lluvia de flechas sin perder un hombre.": "A tartaruga avançou sob a chuva de flechas sem perder um homem.",
    "La sangre ofrecida antes de la batalla dio a los guerreros un valor sin miedo.": "O sangue oferecido antes da batalha deu aos guerreiros uma coragem sem medo.",
    "Los tambores marcaron el paso hasta que el enemigo no soportó más su sonido.": "Os tambores marcaram o passo até que o inimigo não suportou mais seu som.",
