    "Nobles descontentos conspiran contra {}. Nadie sabe quién encabeza la conjura, pero todos saben que existe.": "Nobres descontentes conspiram contra {}. Ninguém sabe quem encabeça a conjura, mas todos sabem que ela existe.",
