    "Alivio de tributos": "Alívio de tributos",
    "Tributos rebajados": "Tributos reduzidos",
    "Tras la revuelta de {}, {} rebaja los tributos en todo el reino.": "Após a revolta de {}, {} reduz os tributos em todo o reino.",
    "Culpar al gobernador": "Culpar o governador",
