    "ante la corte reunida": "diante da corte reunida",
    "{}{} recibe la corona {}. El primer edicto de un reinado dice mucho de lo que vendrá.": "{}{} recebe a coroa {}. O primeiro édito de um reinado diz muito do que virá.",
