    "es ejecutado por la muerte del heredero": "é executado pela morte do herdeiro",
    "Se halla veneno en una copa y una deuda pagada a un criado. {} confiesa en el potro y muere.": "Acha-se veneno numa taça e uma dívida paga a um criado. {} confessa no potro e morre.",
    "Nada se prueba. El silencio pesa más que una sentencia: −# orden.": "Nada se prova. O silêncio pesa mais que uma sentença: −# ordem.",
