    "Seguir adelante": "Seguir em frente",
    "Una consorte extranjera": "Uma consorte estrangeira",
    "Trae consigo su propia fe y su propio capellán.": "Traz consigo sua própria fé e seu próprio capelão.",
    "Comparte vuestra fe, pero no vuestras costumbres.": "Compartilha sua fé, mas não seus costumes.",
    "{} llega de {} con un séquito de damas, consejeros y sacerdotes que hablan entre ellos en su lengua. {}": "{} chega de {} com um séquito de damas, conselheiros e sacerdotes que falam entre si em sua língua. {}",
