    "Los graneros están vacíos y los soldados desertan en busca de pan. En {} se han visto madres ofreciendo a sus hijos a los mercaderes de esclavos a cambio de un saco de harina.": "Os celeiros estão vazios e os soldados desertam em busca de pão. Em {} viram-se mães oferecendo os filhos aos mercadores de escravos em troca de um saco de farinha.",
