    "Tus decisiones forjan tu legado: influye en el orden, la guerra y la diplomacia.": "Suas decisões forjam seu legado: ele influi na ordem, na guerra e na diplomacia.",
    "Un heraldo con rama de olivo cruza las líneas: {} ofrece la paz. Tus generales callan; el tesorero respira.": "Um arauto com ramo de oliveira cruza as linhas: {} oferece a paz. Seus generais se calam; o tesoureiro respira.",
