    "{} propone casar a {} ({} años, {}) con tu {} {} ({}). {} vendría a vivir a tu corte.": "{} propõe casar {} ({} anos, {}) com seu/sua {} {} ({}). {} viria morar na sua corte.",
    "Aceptar la boda": "Aceitar o casamento",
    "La caída de Roma": "A queda de Roma",
