    "Roma ha caído": "Roma caiu",
    "Las carretas crujen bajo el oro de los senadores romanos. En los campamentos, los obispos arrianos y los cautivos nicenos se miran con recelo, y los guerreros ya preguntan cuánto les toca. {} debe decidir qué hacer con lo que la Ciudad dejó.": "As carroças rangem sob o ouro dos senadores romanos. Nos acampamentos, os bispos arianos e os cativos nicenos se olham com desconfiança, e os guerreiros já perguntam quanto lhes cabe. {} deve decidir o que fazer com o que a Cidade deixou.",
    "Llegan a {} jinetes cubiertos de polvo: Roma, que en ocho siglos no había visto un enemigo dentro de sus murallas, ha sido saqueada por los godos. En la corte, unos lloran; otros ya calculan.": "Chegam a {} cavaleiros cobertos de poeira: Roma, que em oito séculos não vira um inimigo dentro de suas muralhas, foi saqueada pelos godos. Na corte, uns choram; outros já calculam.",
    "La noticia llega como llegan las tormentas: Roma ha sido saqueada por los godos de Alarico. Los mercaderes no hablan de otra cosa, y por los caminos aparecen refugiados con códices bajo el brazo y joyas cosidas a la ropa.": "A notícia chega como chegam as tempestades: Roma foi saqueada pelos godos de Alarico. Os mercadores não falam de outra coisa, e pelas estradas surgem refugiados com códices debaixo do braço e joias costuradas na roupa.",
    "Repartir el botín entre los guerreros": "Repartir o saque entre os guerreiros",
    "+# oro, +# infantería en la capital": "+# ouro, +# infantaria na capital",
    "{} reparte el oro de Roma entre sus guerreros. Nadie en el campamento olvidará su nombre.": "{} reparte o ouro de Roma entre seus guerreiros. Ninguém no acampamento esquecerá seu nome.",
    "Devolver los vasos sagrados a las basílicas": "Devolver os vasos sagrados às basílicas",
