    "La ciudad de Dios": "A Cidade de Deus",
    "Los veteranos cuentan en las tabernas lo que vieron en Roma: mármoles, termas, leyes escritas en bronce. Los jóvenes de la corte ya visten a la romana y citan a Virgilio; los viejos escupen al oírlos.": "Nas tabernas, os veteranos contam o que viram em Roma: mármores, termas, leis escritas em bronze. Os jovens da corte já se vestem à romana e citam Virgílio; os velhos cospem ao ouvi-los.",
    "la ciudad de Dios": "a cidade de Deus",
    "la de la razón": "a da razão",
    "Entre los refugiados llegó un {} de dedos manchados de tinta. Escribe que la ciudad de los hombres puede caer sin que caiga {}, y solo pide un copista y una lámpara.": "Entre os refugiados chegou um {} de dedos manchados de tinta. Escreve que a cidade dos homens pode cair sem que caia {}, e só pede um copista e uma lamparina.",
