    "Bajo tu techo se copian los libros que Roma dejó caer.": "Sob o seu teto copiam-se os livros que Roma deixou cair.",
    "En su corte se copiaron los libros que Roma había dejado caer, y algunos aún se leen.": "Em sua corte copiaram-se os livros que Roma deixara cair, e alguns ainda são lidos.",
    "La palabra del refugiado": "A palavra do refugiado",
    "Sus sermones se repiten en cada plaza del reino.": "Seus sermões se repetem em cada praça do reino.",
    "Un refugiado de Roma convirtió la caída del imperio en lección, y el pueblo la aprendió.": "Um refugiado de Roma fez da queda do império uma lição, e o povo a aprendeu.",
    "El profeta despedido": "O profeta dispensado",
    "El refugiado marchó a otra corte. Allí escribió su libro.": "O refugiado partiu para outra corte. Lá escreveu seu livro.",
    "Despidió a un sabio que otros acogieron; la historia suele recordar esas cosas.": "Dispensou um sábio que outros acolheram; a história costuma lembrar essas coisas.",
