    "La costumbre de los padres": "O costume dos pais",
    "El reino da la espalda a Roma y mira a sus antepasados.": "O reino dá as costas a Roma e olha para seus antepassados.",
    "Dio la espalda a Roma y gobernó a la vieja usanza de su pueblo.": "Deu as costas a Roma e governou à velha maneira de seu povo.",
    "El fisco romano": "O fisco romano",
    "Los recaudadores del reino aprenden a contar como los romanos.": "Os coletores do reino aprendem a contar como os romanos.",
    "Tomó de Roma lo que servía: sus registros, sus recaudadores y su paciencia.": "Tomou de Roma o que servia: seus registros, seus coletores e sua paciência.",
    "El foedus": "O foedus",
    "La oferta de Rávena": "A oferta de Ravena",
    "Un tribuno romano, con la capa raída y la dignidad intacta, trae una propuesta de {}: tierras para tu pueblo dentro de las fronteras y la annona cada año, a cambio de que tus guerreros sirvan bajo las águilas. Los romanos lo llaman": "Um tribuno romano, de capa puída e dignidade intacta, traz uma proposta de {}: terras para o seu povo dentro das fronteiras e a annona a cada ano, em troca de que seus guerreiros sirvam sob as águias. Os romanos chamam isso de",
    "Aceptar el foedus": "Aceitar o foedus",
    "+# oro al año (# años), paz con Occidente": "+# ouro por ano (# anos), paz com o Ocidente",
    "{} firma el foedus con Roma. Su pueblo será federado del imperio.": "{} firma o foedus com Roma. Seu povo será federado do império.",
    "Exigir más tierra": "Exigir mais terra",
    "según la diplomacia de {}": "depende da diplomacia de {}",
    "El tribuno cede: más tierra y más annona (+# oro al año durante # años).": "O tribuno cede: mais terra e mais annona (+# ouro por ano por # anos).",
    "El tribuno recoge sus tablillas y se marcha. Roma buscará otros federados.": "O tribuno recolhe suas tabuinhas e parte. Roma buscará outros federados.",
    "Rechazar: no seremos siervos de Roma": "Recusar: não seremos servos de Roma",
    "−# relación con Occidente": "−# relação com o Ocidente",
