    "{} amenaza las fronteras del imperio": "{} ameaça as fronteiras do império",
    "los bagaudas arrasan la Galia": "os bagaudas devastam a Gália",
    "El magister militum de Occidente reclama a sus federados: {} y Roma ya no tiene soldados propios. El tribuno de la capa raída ha vuelto, esta vez con menos cortesía.": "O magister militum do Ocidente convoca seus federados: {} e Roma já não tem soldados próprios. O tribuno da capa puída voltou, desta vez com menos cortesia.",
    "Enviar a tus guerreros": "Enviar seus guerreiros",
