    "la guerra es la guerra": "guerra é guerra",
    "Vuelven cargados de botín y de historias: +# oro.": "Voltam carregados de saque e de histórias: +# ouro.",
    "Vuelven pocos, pero Roma no lo olvida: +# relación más.": "Poucos voltam, mas Roma não esquece: +# de relação.",
    "Enviar excusas y algo de oro": "Enviar desculpas e algum ouro",
