    "Tierra propia": "Terra própria",
    "Roma se apaga como una vela. La annona llega tarde o no llega, y en tus tierras ya nadie recuerda al tribuno. Tus nobles dicen que es hora de que {} se llame {} de su propia tierra, y no huésped de nadie.": "Roma se apaga como uma vela. A annona chega tarde ou não chega, e em suas terras já ninguém se lembra do tribuno. Seus nobres dizem que é hora de {} se chamar {} de sua própria terra, e não hóspede de ninguém.",
