    "Roma concede a {} el título de patricio: un trono bárbaro con manto romano (+# oro al año, # años).": "Roma concede a {} o título de patrício: um trono bárbaro com manto romano (+# ouro por ano, # anos).",
    "Roma se niega. Los nobles toman la negativa como permiso para proclamar el reino.": "Roma se recusa. Os nobres tomam a recusa como licença para proclamar o reino.",
    "Libres de Roma": "Livres de Roma",
    "Tu pueblo no sirve a nadie.": "Seu povo não serve a ninguém.",
    "Rechazó el foedus de Roma y no sirvió a ningún emperador.": "Recusou o foedus de Roma e não serviu a nenhum imperador.",
