    "Danubio": "Danúbio",
    "Al otro lado del {}, miles de familias —{}— esperan en la orilla con sus carros y sus rebaños. Su rey pide tierra a cambio de espadas. Si se le niega, dicen, cruzará igualmente cuando el río se hiele.": "Do outro lado do {}, milhares de famílias —{}— esperam na margem com suas carroças e rebanhos. Seu rei pede terra em troca de espadas. Se lhe for negada, dizem, atravessará mesmo assim quando o rio congelar.",
    "Asentarlos como federados": "Assentá-los como federados",
